import Foundation

/// What each Lifestream event is for, how often one install may send it, what it carries and which apps may send it, one entry per event in registry order. Generated by `midgar gen --write` from registry/signals.yaml. Edit the registry, not this file.
public enum MidgarSignalCatalog {
