    public static let entries: [Entry] = [
        Entry(
            name: "app.launch",
            purpose: "The app was opened.",
            uniqueness: .each,
            carriesCohort: false,
            isReserved: true,
            props: [],
            measurements: [],
            apps: []
        ),
        Entry(
            name: "app.active",
            purpose: "Daily, weekly and monthly active installs.",
            uniqueness: .perPeriod,
            carriesCohort: true,
            isReserved: false,
            props: [Prop(name: "period", values: .list(MidgarSignal.Period.allCases.map(\.rawValue)))],
            measurements: [],
            apps: []
